	cgal_subdomain(const int id, const std::string name, const double size);
	~cgal_subdomain();

	// Get domain id
	int DomainID();
	// Get domain name
	std::string DomainName();
	// Get domain size in mesh generation
	double DomainSize();
	// Get domain label
	char DomainLabel();

	// Set domain id
	void setDomainID(const int id);
	// Set domain name
	void setDomainName(const std::string name);
	// Set domain size in mesh generation
	void setDomainSize(const double size);
	// Set domain label
	void setDomainLabel(const char label);

protected:

private:
